function shopCard(item,inventory){let el=document.createElement('article');el.className='shop-item';if(item.outfit)el.dataset.outfit=item.outfit;el.dataset.slot=item.slot;if(item.exclusive)el.classList.add('exclusive');const art=document.createElement('div');art.className='item-art';art.style.setProperty('--item-color',item.color);let character=document.createElement('div');character.className='item-character';paint(character,item.character||(inventory?dressChar:profile.char),'idle',true,previewLook(item));art.append(character);const kind=document.createElement('span');kind.className='item-kind';kind.textContent={cloth:'ROPA',eyes:'OJOS',hair:'CABELLO',accessory:'ACCESORIO',set:'SET'}[item.slot];art.append(kind);if(item.slot==='eyes'){art.classList.add('eye-preview')}el.append(art);const title=document.createElement('h3');title.textContent=item.name;el.append(title);const desc=document.createElement('p');desc.textContent=item.desc;el.append(desc);const btn=document.createElement('button');btn.className='secondary';let has=own(item.id)||(!item.exclusive&&item.parts&&item.parts.every(own));btn.textContent=inventory?(equipped(item,dressChar)?'✓ Equipado':'Equipar'):has?'✓ Adquirido':'✦ '+item.price+' BC';btn.disabled=inventory?equipped(item,dressChar):has||profile.coins<item.price;btn.onclick=()=>inventory?equip(item):buy(item);if(!inventory){el.onmouseenter=()=>renderShopSpotlight(item);el.onfocusin=()=>renderShopSpotlight(item)}el.append(btn);return el}
function buy(i){if(own(i.id)||i.parts?.every(own)||profile.coins<i.price)return;profile.coins-=i.price;grantItem(i);store.set('profile',profile);syncProfile();renderShop();$('shopStatus').textContent=i.name+' añadido al vestidor.'}
function equip(i){if(i.character&&i.character!==dressChar)dressChar=i.character;if(!own(i.id)&&(i.exclusive||!i.parts?.every(own)))return;let l=i.slot==='set'?previewLook(i):{...lookFor(dressChar),[i.slot]:i.value};l.outfit=CherryMotion.appearance(dressChar,l).outfit;l.cosmeticVersion=2;profile.looks[dressChar]=l;store.set('profile',profile);renderInventory();syncProfile();$('inventoryStatus').textContent=i.name+' equipado.'}
function renderShopSpotlight(item){if(!item)return;shopFocusId=item.id;$('shopFocusName').textContent=item.name;$('shopFocusDesc').textContent=item.desc;const labels={set:'SET',cloth:'ROPA',hair:'CABELLO',eyes:'OJOS',accessory:'ACCESORIO'};const ownedLabel=own(item.id)||(!item.exclusive&&item.parts&&item.parts.every(own))?' · ADQUIRIDO':'';$('shopFocusMeta').textContent=(labels[item.slot]||'ITEM')+(item.price?` · ${item.price} BC`:' · EXCLUSIVO')+ownedLabel;paint($('shopPreview'),profile.char,'idle',true,previewLook(item))}
function renderShop(){let g=$('shopGrid');g.replaceChildren();let list=catalog.filter(i=>!i.exclusive&&(shopFilter==='all'||i.slot===shopFilter));for(let i of list)g.append(shopCard(i,false));$('shopBalance').textContent=num(profile.coins)+' BC';if($('shopBalanceLarge'))$('shopBalanceLarge').textContent=num(profile.coins)+' Beat Coins';renderShopSpotlight(list.find(i=>i.id===shopFocusId)||list.find(i=>i.slot==='set')||list[0]||lookup('set-moon'))}
function renderClosetCast(){const root=$('closetCast');if(!root)return;root.replaceChildren();for(const c of characters){const button=document.createElement('button');button.className='closet-character'+(c===dressChar?' selected':'');const a=document.createElement('div');a.className='closet-art';paint(a,c,'idle');const b=document.createElement('b');b.textContent=charNames[c];const k=document.createElement('small');k.textContent=c===profile.char?'JUGABLE':'VER';button.append(a,b,k);button.onclick=()=>{dressChar=c;renderInventory()};root.append(button)}$('equipCharacter').textContent=dressChar===profile.char?'✓ Personaje activo':'Usar '+charNames[dressChar];$('equipCharacter').disabled=dressChar===profile.char;}
