for(let [id,m] of [['classicMode','classic'],['advancedMode','advanced'],['customMode','custom']])$(id).onclick=()=>{draftMode=m;if(m!=='custom')draftBindings=defaults(m);bindingDir=null;renderBindings()};$('resetBindings').onclick=()=>{draftBindings=defaults(draftMode);bindingDir=null;renderBindings()};document.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-settings]').forEach(x=>x.classList.toggle('selected',x===b));$('audioSettings').classList.toggle('hidden',b.dataset.settings!=='audio');$('controlSettings').classList.toggle('hidden',b.dataset.settings!=='controls');$('redeemSettings').classList.toggle('hidden',b.dataset.settings!=='redeem');bindingDir=null});window.addEventListener('keydown',e=>{if(!$('settings').open||!bindingDir)return;e.preventDefault();e.stopImmediatePropagation();let k=normalizeKey(e.key);if(k==='Escape'){bindingDir=null;renderBindings();return}if(!/^(Arrow(Left|Right|Up|Down)|[a-z0-9])$/.test(k)||Object.keys(draftBindings).some(d=>d!==bindingDir&&draftBindings[d]===k)){$('bindStatus').textContent='Tecla no válida o ya asignada.';return}draftBindings[bindingDir]=k;draftMode='custom';bindingDir=null;$('bindStatus').textContent='Tecla asignada. Guarda los ajustes.';renderBindings()},true);
