function endReview(){reviewToken++;cancelAnimationFrame(reviewRaf);resultLife.clear();stopCelebration();reviewDone=false;}
function startReview(){let token=++reviewToken;reviewDone=false;const g=$('reviewGraph');g.replaceChildren();let bins=Array.from({length:32},()=>({good:0,total:0,bot:0,bt:0}));for(let e of p.events){let i=Math.min(31,Math.floor(e.t/CBChart.endFor(chart,diff)*32));bins[i].good+=weights[e.g];bins[i].total++}for(let e of b.events){let i=Math.min(31,Math.floor(e.t/CBChart.endFor(chart,diff)*32));bins[i].bot+=weights[e.g];bins[i].bt++}for(let bin of bins){let cell=document.createElement('div');cell.className='review-bin';let a=document.createElement('i'),z=document.createElement('b');a.style.height=(bin.total?bin.good/bin.total*100:0)+'%';z.style.height=(bin.bt?bin.bot/bin.bt*100:0)+'%';cell.append(a,z);g.append(cell)}
 let start=performance.now(),last=[-1,-1],poses=['',''];$('reviewPName').textContent=profile.name;paint($('pReviewArt'),profile.char,'idle');function summarize(s,limit,side,i){let ev=s.events.filter(e=>e.t<=limit),sum=0,cur=0,max=0,miss=0;for(let e of ev){sum+=weights[e.g];if(e.g==='miss'){cur=0;miss++}else cur++;max=Math.max(max,cur)}let partial=Math.round(13000*sum/notes.length),starsN=thresholds.filter(x=>partial>=x).length;$(side+'ReviewScore').textContent=num(partial);$(side+'ReviewStars').textContent=stars(starsN);$(side+'ReviewStats').textContent=`${miss} fallos · ${max} combo máx.`;$(side+'ReviewAcc').textContent=`${ev.length?Math.round(sum/ev.length*100):100}% precisión`;let bucket=Math.floor(limit/12);if(bucket!==last[i]){last[i]=bucket;let recent=ev.filter(e=>e.t>=limit-15);let quality=recent.length?recent.reduce((n,e)=>n+weights[e.g],0)/recent.length:1;let pose=recent.length===0?'idle':quality<.48?'miss':quality>.83?'perfect':'ready';if(pose!==poses[i]){poses[i]=pose;paint($(side+'ReviewArt'),i?other():profile.char,pose,!i);retrigger($(side+'ReviewArt'),'review-react')}$(side+'ReviewReaction').textContent=pose==='miss'?'¡A recuperar!':pose==='perfect'?'¡Gran racha!':pose==='ready'?'¡Buen ritmo!':'Preparación';}}
 function tick(now){if(token!==reviewToken||state!=='results')return;let f=Math.min(1,(now-start)/9200),limit=f*CBChart.endFor(chart,diff);$('reviewProgress').firstElementChild.style.width=f*100+'%';[...g.children].forEach((e,i)=>e.classList.toggle('revealed',i/32<=f));summarize(p,limit,'p',0);summarize(b,limit,'b',1);$('reviewStats').textContent=`${fmt(limit)} / ${fmt(CBChart.endFor(chart,diff))} · recorrido de la canción`;if(now-start<10200)reviewRaf=requestAnimationFrame(tick)}resultLife.start(10200);reviewRaf=requestAnimationFrame(tick)}
function fullReplayMotion(){return settings.deviceProfile==='mobile'?settings.mobileReplayMotion===true:settings.pcReplayMotion!==false}
function revealWinner(){if(reviewDone||state!=='results')return;$('teamReview').classList.add('hidden');reviewDone=true;cancelAnimationFrame(reviewRaf);$('reviewStage').classList.add('hidden');$('winnerStage').classList.remove('hidden');retrigger($('winnerStage'),'winner-enter');let started=performance.now(),winToken=reviewToken;function victoryMotion(now){if(state!=='results'||!reviewDone||reviewToken!==winToken)return;for(let art of document.querySelectorAll('[data-motion-result]'))CherryMotion.update(art,art.dataset.paintChar,art.dataset.motionCustom==='yes'?lookFor(art.dataset.paintChar):emptyLook(),art.dataset.motionResult,(now-started)/1000);requestAnimationFrame(victoryMotion)}if(fullReplayMotion())requestAnimationFrame(victoryMotion);retrigger($('resultStars'),'stars-enter');}
