// All economy mutations use the same profile instance and storage as shop and inventory.
const rarityLabel={exotic:'EXÓTICO',legendary:'LEGENDARIO',epic:'ÉPICO',rare:'RARO'};
const pools={exotic:['exotic-galaxy','zomby-nexus'],legendary:['legend-nebula','legend-rose','zomby-astral','zomby-night'],epic:['set-ocean','set-plum','zomby-starmap','zomby-void'],rare:['accessory-moon','accessory-notes','accessory-bow','eyes-aqua','eyes-violet','cloth-gold','hair-peach','hair-silver','hair-rose','cloth-blue','cloth-crimson','eyes-emerald','eyes-rose']};
function gachaCard(item,rarity,hero=false){const card=document.createElement('div');card.className='gacha-item '+rarity+(hero?' hero':'');card.dataset.outfit=item.outfit||previewLook(item).outfit||'original';let badge=document.createElement('span');badge.className='gacha-rarity';badge.textContent=rarityLabel[rarity];let art=document.createElement('div');art.className='gacha-art';paint(art,item.character||profile.char,'idle',true,previewLook(item));art.dataset.outfit=previewLook(item).outfit||item.outfit||'original';let name=document.createElement('b');name.textContent=item.name;let desc=document.createElement('small');desc.className='gacha-desc';desc.textContent=item.slot==='set'?'SET COMPLETO':item.desc||'';card.append(badge,art,name,desc);return card}
function renderGachaHistory(){const box=$('gachaHistory');box.replaceChildren();let title=document.createElement('h3');title.textContent='Últimas recompensas';box.append(title);for(let entry of profile.gachaHistory.slice(0,3)){let row=document.createElement('div');row.className='gacha-pull '+entry.rarity;let art=document.createElement('div');art.className='gacha-history-art';let item=catalog.find(i=>i.id===entry.id)||catalog.find(i=>i.name===entry.name)||lookup(pools.legendary[0]);paint(art,item.character||profile.char,'idle',true,previewLook(item));let info=document.createElement('div');info.className='gacha-history-info';let b=document.createElement('b');b.textContent=entry.name;let small=document.createElement('small');small.textContent=(rarityLabel[entry.rarity]||entry.rarity)+(entry.duplicate?' · DUPLICADO +15 BC':'');let time=document.createElement('span');time.textContent=entry.time?new Date(entry.time).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}):'';info.append(b,small,time);row.append(art,info);box.append(row)}if(!profile.gachaHistory.length){let empty=document.createElement('p');empty.className='subtle';empty.textContent='Aún no hay tiradas.';box.append(empty)}}
let featurePage=0;function paginateFeatures(reset=false){const grid=$('featuredRewards');if(!grid)return;const cards=[...grid.children];if(reset)featurePage=0;const cap=innerWidth>=1000&&innerHeight<700?2:4, n=Math.max(1,Math.ceil(cards.length/cap));featurePage=Math.min(featurePage,n-1);cards.forEach((card,i)=>{card.hidden=i<featurePage*cap||i>=(featurePage+1)*cap});let bar=$('featuredPager');if(!bar){bar=document.createElement('div');bar.id='featuredPager';bar.className='catalog-pager';grid.after(bar)}bar.replaceChildren();let a=document.createElement('button'),b=document.createElement('button'),text=document.createElement('span');a.className=b.className='secondary';a.textContent='‹';b.textContent='›';text.textContent=`${featurePage+1} / ${n} · ${cards.length} premios`;a.disabled=featurePage===0;b.disabled=featurePage===n-1;a.onclick=()=>{featurePage--;paginateFeatures()};b.onclick=()=>{featurePage++;paginateFeatures()};bar.append(a,text,b);bar.hidden=n<=1;}window.addEventListener('resize',()=>paginateFeatures());
function renderGacha(){if(spinBusy)return;let track=$('gachaTrack');track.style.transition='none';track.style.transform='none';track.replaceChildren();for(let id of [...eligiblePool('exotic'),...eligiblePool('legendary'),...eligiblePool('epic'),...eligiblePool('rare')]){let r=Object.keys(pools).find(r=>pools[r].includes(id));track.append(gachaCard(lookup(id),r))}let features=$('featuredRewards');features.replaceChildren();for(let id of [...eligiblePool('exotic'),...eligiblePool('legendary'),...eligiblePool('epic')])features.append(gachaCard(lookup(id),Object.keys(pools).find(r=>pools[r].includes(id)),true));paginateFeatures(true);let banner=document.querySelector('.gacha-banner');let spot=banner.querySelector('.legend-spotlight');if(!spot){spot=document.createElement('div');spot.className='legend-spotlight';banner.append(spot)}let spotlight=lookup(eligiblePool('exotic')[0]);spot.replaceChildren();let art=document.createElement('div');art.className='legend-preview';paint(art,spotlight.character||profile.char,'idle',true,previewLook(spotlight));let info=document.createElement('div');info.innerHTML=`<span class="mini">EXÓTICO · ${spotlight.character?'GALAXY NEXUS':'ASTRAL GALAXY'}</span><b>${spotlight.name}</b><small>${spotlight.desc}</small>`;spot.append(art,info);let variants=banner.querySelector('.galaxy-cast');if(!variants){variants=document.createElement('div');variants.className='galaxy-cast';banner.append(variants)}variants.replaceChildren();for(let c of (spotlight.character?[spotlight.character]:characters)){let v=document.createElement('div'),a=document.createElement('div'),n=document.createElement('small');a.className='galaxy-variant';paint(a,c,'idle',true,previewLook(spotlight));n.textContent=charNames[c];v.append(a,n);variants.append(v)}$('ticketBalance').textContent=profile.tickets+' BCR';$('buyTicket').disabled=profile.coins<40;$('spinGacha').disabled=profile.tickets<1;$('spinTen').disabled=profile.tickets<10;renderGachaHistory()}
$('buyTicket').onclick=()=>{if(spinBusy||profile.coins<40)return;profile.coins-=40;profile.tickets++;store.set('profile',profile);syncProfile();renderGacha();$('gachaStatus').textContent='Beat Crystal adquirido. ¡Listo para invocar!'};
let summonPool='all';function eligiblePool(r){let pool=pools[r];if(r==='rare'||summonPool==='all')return pool;return pool.filter(id=>summonPool==='zomby'?id.startsWith('zomby-'):!id.startsWith('zomby-'))}function pullOne(){let roll=Math.random(),rarity=roll<.02?'exotic':roll<.10?'legendary':roll<.37?'epic':'rare',pool=eligiblePool(rarity),item=lookup(pool[Math.floor(Math.random()*pool.length)]),duplicate=own(item.id)||(!item.exclusive&&item.parts?.every(own));if(duplicate)profile.coins+=15;else grantItem(item);profile.gachaHistory.unshift({id:item.id,name:item.name,rarity,time:new Date().toISOString(),duplicate});return {item,rarity,duplicate}}
